export function findById(id) { return MEDICINES.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return MEDICINES.slice();
  return MEDICINES.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return MEDICINES.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return MEDICINES.filter(x => x.enabled !== false); }
export const COUNT = MEDICINES.length;
